module viterbi_decoder (
    input wire clk,
    input wire reset,
    input wire input_bit,
    output reg [1:0] output_bit
);
    reg [1:0] state, next_state;
    reg [1:0] path_metric [0:3]; // Storing path metrics for 4 states

    // State definitions
    localparam S0 = 2'd0, S1 = 2'd1, S2 = 2'd2, S3 = 2'd3;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
            output_bit <= 2'b00;
            path_metric[0] <= 0; 
            path_metric[1] <= 0; 
            path_metric[2] <= 0; 
            path_metric[3] <= 0; 
        end else begin
            state <= next_state;
            // Update path metrics based on input_bit and current state
            // For simplicity, let's assume a basic metric update
            path_metric[state] <= path_metric[state] + input_bit;
            // Generate output based on current state (for demonstration)
            output_bit <= state; // Just an example output
        end
    end

    // Combinational logic for next state
    always @(*) begin
        case (state)
            S0: next_state = (input_bit) ? S1 : S2;
            S1: next_state = (input_bit) ? S0 : S3;
            S2: next_state = (input_bit) ? S3 : S0;
            S3: next_state = (input_bit) ? S2 : S1;
            default: next_state = S0;
        endcase
    end
endmodule

