module turbo_decoder (  
    input wire clk,  
    input wire reset,  
    input wire [1:0] encoded_bits,  
    output reg [1:0] decoded_bits  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, DECODE = 2'b01, OUTPUT = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            decoded_bits <= 2'b00;  
        end  
        else begin  
            case (state)  
                IDLE: state <= DECODE;  
                DECODE: begin  
                    // Simple soft decision logic for demonstration  
                    decoded_bits <= (encoded_bits == 2'b00) ? 2'b00 :  
                                    (encoded_bits == 2'b01) ? 2'b01 :  
                                    (encoded_bits == 2'b10) ? 2'b10 : 2'b11;  
                    state <= OUTPUT;  
                end  
                OUTPUT: state <= IDLE;  
            endcase  
        end  
    end  
endmodule

