module deserializer (
    input wire clk,
    input wire reset,
    input wire start,
    input wire serial_in,
    output reg [7:0] parallel_out
);
    reg [2:0] bit_count; // 3 bits to count from 0 to 7

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parallel_out <= 8'b0;
            bit_count <= 3'b0;
        end else if (start) begin
            if (bit_count < 3'd7) begin
                parallel_out <= {serial_in, parallel_out[7:1]};
                bit_count <= bit_count + 1;
            end else begin
                parallel_out <= {serial_in, parallel_out[7:1]};
                bit_count <= 3'b0; // Reset after 8 bits are received
            end
        end
    end
endmodule

