module reg_4bit (D, CLK, LOAD, CLEAR, Q);
input [3:0] D;
input CLK;
input LOAD;
input CLEAR;
output reg [3:0] Q;

always @(posedge CLK or posedge CLEAR) begin
    if (CLEAR) begin
        Q <= 4'b0000;
    end
    else if (LOAD) begin
        Q <= D;
    end
end

endmodule

