description:
Implement a sign extension circuit that takes a 16-bit input and produces a 32-bit output. The module replicates the most significant bit (sign bit) of the input to fill the upper 16 bits of the output, ensuring that the sign of the original number is preserved when extending its bit-width.
module top_module(	
	in,

	out
);

code:
module top_module(	
	in,

	out
);parameter INPUT_DWIDTH = 16;
	parameter OUTPUT_DWIDTH = 32;

   input	[INPUT_DWIDTH-1:0]	in;

   output [OUTPUT_DWIDTH-1:0] out; 

	localparam SIGN_BIT_LOCATION = INPUT_DWIDTH-1;
	localparam SIGN_BIT_REPLICATION_COUNT = OUTPUT_DWIDTH - INPUT_DWIDTH;

	assign out = {{SIGN_BIT_REPLICATION_COUNT{in[SIGN_BIT_LOCATION]}},in[INPUT_DWIDTH-1:0]};

endmodule

