module top_module (
        input clk,
        input areset,
        input x,
        output reg z);parameter S0=2'b00, S1=2'b01, S2=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= S0;
		else begin
			case (state)
				S0: state <= x ? S1 : S0;
				S1: state <= x ? S1 : S2;
				S2: state <= x ? S1 : S0;
			endcase
		end
	end

	assign z = (state == S2 && x==0);

endmodule

