description:
Design a 4-to-1 multiplexer that selects one of four input data lines (data_in[0] to data_in[3]) based on a 2-bit selection signal (sel). The output (data_out) reflects the value of the selected input, where sel indicates which input to forward: when sel is 00, output data_in[0]; when sel is 01, output data_in[1]; when sel is 10, output data_in[2]; and when sel is 11, output data_in[3].
module top_module(
    input [3:0] data_in,
    input [1:0] sel,
    output reg data_out
);

code:
module top_module(
    input [3:0] data_in,
    input [1:0] sel,
    output reg data_out
);wire sel_0_bar;
    wire sel_1_bar;

    assign sel_0_bar = ~sel[0];
    assign sel_1_bar = ~sel[1];

    wire and_1;
    wire and_2;
    wire and_3;
    wire and_4;
    wire or_1;
    wire or_2;

    assign and_1 = data_in[0] & sel_0_bar & sel_1_bar;
    assign and_2 = data_in[1] & sel_0_bar & sel[1];
    assign and_3 = data_in[2] & sel[0] & sel_1_bar;
    assign and_4 = data_in[3] & sel[0] & sel[1];

    assign or_1 = and_1 | and_2;
    assign or_2 = and_3 | and_4;

    assign data_out = or_1 | or_2;

endmodule

