module pedestrian_crossing (
	input clk,
	input resetn,
	input request,
	output walk);

	parameter IDLE=0, WALK=1, WAIT=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == WALK) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = request ? WALK : IDLE;
			WALK: next_state = (counter == 4'b1111) ? WAIT : WALK;
			WAIT: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign walk = (state == WALK);
endmodule

