description:
Design a 16-to-4 priority encoder that identifies the highest-order bit set in a 16-bit input signal. The output is a 4-bit code indicating the position of that highest set bit, with priority given to the least significant set bit in the case of multiple bits being high. If no bits are set, the output defaults to position 15.
module top_module(
  input [15:0] data,
  output reg [3:0] position
);

Design a synchronous memory module with asynchronous read capabilities. The module allows for writing data to a specified address when the write chip select (`wr_cs`) is active, triggered by the rising edge of the clock (`wr_clk`). It has a memory depth of 32,768 words, each 8 bits wide. When the read chip select (`rd_cs`) is active, it drives the read data (`rd_data`) output with the content stored at the specified address; otherwise, it outputs a high-impedance state. This module serves as a basic RAM for applications requiring both write and read operations in digital systems.
module top_module(

  rd_data, 

  wr_clk, wr_data, wr_cs, addr, rd_cs
  );

code:
module top_module(

  rd_data, 

  wr_clk, wr_data, wr_cs, addr, rd_cs
  );parameter asz = 15,
	    depth = 32768;

  input       wr_clk;
  input [7:0] wr_data;
  input       wr_cs;

  input [asz-1:0] addr;
  inout [7:0] 	  rd_data;
  input 	  rd_cs;

  reg [7:0] 	  mem [0:depth-1];

  always @(posedge wr_clk)
    begin
      if (wr_cs)
	mem[addr] <= #1 wr_data;
    end

  assign rd_data = (rd_cs) ? mem[addr] : {8{1'bz}};

endmodule

module top_module(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  rd_data_count,
  wr_data_count
);input rst;
input wr_clk;
input rd_clk;
input [63 : 0] din;
input wr_en;
input rd_en;
output [63 : 0] dout;
output full;
output empty;
output [8 : 0] rd_data_count;
output [8 : 0] wr_data_count;

reg [63:0] mem [511:0];
reg [8:0] rd_ptr;
reg [8:0] wr_ptr;
reg [8:0] rd_data_count_reg;
reg [8:0] wr_data_count_reg;
wire [8:0] rd_data_count;
wire [8:0] wr_data_count;

assign rd_data_count = rd_data_count_reg;
assign wr_data_count = wr_data_count_reg;

assign full = ((wr_ptr == rd_ptr) && wr_en && !rd_en);
assign empty = ((wr_ptr == rd_ptr) && !wr_en && rd_en);

assign dout = mem[rd_ptr];

always @(posedge wr_clk or negedge rst) begin
  if (!rst) begin
    wr_ptr <= 0;
    wr_data_count_reg <= 0;
  end else if (wr_en && !full) begin
    mem[wr_ptr] <= din;
    wr_ptr <= wr_ptr + 1;
    wr_data_count_reg <= wr_data_count_reg + 1;
  end
end

always @(posedge rd_clk or negedge rst) begin
  if (!rst) begin
    rd_ptr <= 0;
    rd_data_count_reg <= 0;
  end else if (rd_en && !empty) begin
    rd_ptr <= rd_ptr + 1;
    rd_data_count_reg <= rd_data_count_reg + 1;
  end
end

endmodule

