parameter pW = 10;
parameter wL = 15;
parameter wW = 15;
parameter wP = 15;


always@(posedge clk, posedge rst)
begin
	if(rst) body <= 0;
	else begin
		if(x < poX+pL && x > poX && y < poY+wL+pW && y >poY+wL) body <= 1;
		else body <= 0;
	end
end


always@(posedge clk, posedge rst)
