    output reg clk_pulse_1Hz
    );

code:
module top_module(
    input clk_100MHz,
    output reg clk_pulse_1Hz
    );parameter countMax=99999999;
    reg [26:0] count;
    always @(posedge clk_100MHz)
        if(count==countMax)
            begin
                count<=0;
                clk_pulse_1Hz<=1;
            end
        else
            begin
                count<=count+1;
                clk_pulse_1Hz<=0;
            end
endmodule

